import{_ as p,a0 as l,w as d,s as r,I as s,x as a,a1 as e,A as n,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Fedora 中结合权能使用 Podman | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 中结合权能使用 Podman | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 中结合权能使用 Podman | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 中结合权能使用 Podman | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201116 Podman with capabilities on Fedora","title":"在 Fedora 中结合权能使用 Podman","tag":"202011","desc":""},"relativePath":"202011/20201116 Podman with capabilities on Fedora.md","filePath":"[post].md"}'),g={name:"202011/20201116 Podman with capabilities on Fedora.md"};function u(m,i,h,b,k,f){const t=l("Link");return d(),r("div",null,[i[31]||(i[31]=s("h1",{id:"在-fedora-中结合权能使用-podman",tabindex:"-1"},[a("在 Fedora 中结合权能使用 Podman "),s("a",{class:"header-anchor",href:"#在-fedora-中结合权能使用-podman","aria-label":"Permalink to “在 Fedora 中结合权能使用 Podman”"},"​")],-1)),i[32]||(i[32]=s("p",null,[s("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/10/podman-816x345.jpg",alt:""})],-1)),s("p",null,[i[2]||(i[2]=a("容器化是一项蓬勃发展的技术。在不久的将来，多达百分之七十五的全球组织可能会运行某种类型的容器化技术。由于广泛使用的技术更容易成为黑客攻击的目标，因此保护容器的安全就显得尤为重要。本文将演示如何使用 POSIX ",-1)),s("ruby",null,[e(t,{href:"https://www.linuxjournal.com/magazine/making-root-unprivileged"},{default:n(()=>[...i[0]||(i[0]=[a("权能",-1)])]),_:1}),i[1]||(i[1]=s("rt",null,"Capability",-1))]),i[3]||(i[3]=a(" 来保护 Podman 容器的安全。Podman 是 RHEL8 中默认的容器管理工具。",-1))]),i[33]||(i[33]=s("h3",{id:"确定-podman-容器的权限模式",tabindex:"-1"},[a("确定 Podman 容器的权限模式 "),s("a",{class:"header-anchor",href:"#确定-podman-容器的权限模式","aria-label":"Permalink to “确定 Podman 容器的权限模式”"},"​")],-1)),s("p",null,[i[6]||(i[6]=a("容器以特权模式或无特权模式运行。在特权模式下，",-1)),e(t,{href:"https://linuxcontainers.org/lxc/security/#privileged-containers"},{default:n(()=>[...i[4]||(i[4]=[a("容器的 uid 0 被映射到宿主机的 uid 0",-1)])]),_:1}),i[7]||(i[7]=a("。对于某些情况，无特权的容器",-1)),e(t,{href:"https://github.com/containers/podman/blob/master/rootless.md"},{default:n(()=>[...i[5]||(i[5]=[a("缺乏对宿主机资源的充分访问能力",-1)])]),_:1}),i[8]||(i[8]=a("。但不管其操作模式如何，包括",-1)),i[9]||(i[9]=s("ruby",null,[a("强制访问控制"),s("rt",null,"Mandatory Access Control")],-1)),i[10]||(i[10]=a("（MAC：如 apparmor、SELinux 等）、seccomp 过滤器、删除",-1)),i[11]||(i[11]=s("ruby",null,[a("权能"),s("rt",null,"Capability")],-1)),i[12]||(i[12]=a("、命名空间等在内的技术有助于确保容器的安全。",-1))]),i[34]||(i[34]=o(`<p>要从容器外部确定特权模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman inspect --format=&quot;{{.HostConfig.Privileged}}&quot; &lt;container id&gt;</span></span></code></pre></div><p>如果上面的命令返回 <code>true</code>，那么容器在特权模式下运行。如果返回 <code>false</code>，那么容器在非特权模式下运行。</p><p>要从容器内部确定特权模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip link add dummy0 type dummy</span></span></code></pre></div><p>如果该命令允许你创建一个接口，那么你运行的是一个特权容器，否则你运行的是一个非特权容器。</p><h3 id="权能" tabindex="-1">权能 <a class="header-anchor" href="#权能" aria-label="Permalink to “权能”">​</a></h3><p>命名空间隔离了容器的进程，使其无法任意访问宿主机的资源，也无法访问在同一宿主机上运行的其他容器的资源。然而，在<strong>特权</strong>容器内的进程仍然可以做一些事情，如改变 IP 路由表、跟踪任意进程和加载内核模块。<ruby>权能<rt>Capability</rt></ruby>允许人们对容器内的进程可以访问或更改的资源施加更细微的限制，即使容器在特权模式下运行也一样。权能还允许人们为无特权的容器分配它本来不会拥有的特权。</p><p>例如，如果要将 <code>NET_ADMIN</code> 功能添加到一个无特权的容器中，以便在容器内部创建一个网络接口，你可以用下面的参数运行 <code>podman</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@vm1 ~]# podman run -it --cap-add=NET_ADMIN centos</span></span>
<span class="line"><span>[root@b27fea33ccf1 /]# ip link add dummy0 type dummy</span></span>
<span class="line"><span>[root@b27fea33ccf1 /]# ip link</span></span></code></pre></div><p>上面的命令演示了在一个无特权的容器中创建一个 <code>dummy0</code> 接口。如果没有 <code>NET_ADMIN</code> 权能，非特权容器将无法创建接口。上面的命令演示了如何将一个权能授予一个无特权的容器。</p>`,11)),s("p",null,[i[14]||(i[14]=a("目前，大约有 ",-1)),e(t,{href:"https://man7.org/linux/man-pages/man7/capabilities.7.html"},{default:n(()=>[...i[13]||(i[13]=[a("39 种权能",-1)])]),_:1}),i[15]||(i[15]=a("可以被授予或拒绝。特权容器默认会被授予许多权能。建议从特权容器中删除不需要的权能，以使其更加安全。",-1))]),i[35]||(i[35]=o(`<p>要从容器中删除所有权能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman run -it -d --name mycontainer --cap-drop=all centos</span></span></code></pre></div><p>列出一个容器的权能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman exec -it 48f11d9fa512 capsh --print</span></span></code></pre></div><p>上述命令显示没有向容器授予任何权能。</p><p>请参考 <code>capabilities</code> 手册页以获取完整的权能列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man capabilities</span></span></code></pre></div><p>可以使用 <code>capsh</code> 命令来列出目前拥有的权能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ capsh --print</span></span></code></pre></div><p>作为另一个例子，下面的命令演示了如何从容器中删除 <code>NET_RAW</code> 权能。如果没有 <code>NET_RAW</code> 权能，就不能从容器中 <code>ping</code> 互联网上的服务器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman run -it --name mycontainer1 --cap-drop=net_raw centos</span></span>
<span class="line"><span>&gt;&gt;&gt; ping google.com (will output error, operation not permitted)</span></span></code></pre></div><p>最后一个例子，如果你的容器只需要 <code>SETUID</code> 和 <code>SETGID</code> 权能，你可以删除所有权能，然后只重新添加这两个权能来实现这样的权限设置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman run -d --cap-drop=all --cap-add=setuid --cap-add=setgid fedora sleep 5 &gt; /dev/null; pscap | grep sleep</span></span></code></pre></div><p>上面的 <code>pscap</code> 命令会显示容器被授予的权能。</p><p>我希望你喜欢这个关于如何使用权能来保护 Podman 容器的简短探索。</p><p>谢谢！</p><hr>`,17)),s("p",null,[i[17]||(i[17]=a("via: ",-1)),e(t,{href:"https://fedoramagazine.org/podman-with-capabilities-on-fedora/"},{default:n(()=>[...i[16]||(i[16]=[a("https://fedoramagazine.org/podman-with-capabilities-on-fedora/",-1)])]),_:1})]),s("p",null,[i[22]||(i[22]=a("作者：",-1)),e(t,{href:"https://fedoramagazine.org/author/shiwanibiradar/"},{default:n(()=>[...i[18]||(i[18]=[a("shiwanibiradar",-1)])]),_:1}),i[23]||(i[23]=a(" 选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...i[19]||(i[19]=[a("lujun9972",-1)])]),_:1}),i[24]||(i[24]=a(" 译者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:n(()=>[...i[20]||(i[20]=[a("geekpi",-1)])]),_:1}),i[25]||(i[25]=a(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:n(()=>[...i[21]||(i[21]=[a("wxy",-1)])]),_:1})]),s("p",null,[i[28]||(i[28]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[26]||(i[26]=[a("LCTT",-1)])]),_:1}),i[29]||(i[29]=a(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:n(()=>[...i[27]||(i[27]=[a("Linux中国",-1)])]),_:1}),i[30]||(i[30]=a(" 荣誉推出",-1))])])}const T=p(g,[["render",u]]);export{C as __pageData,T as default};
